BEGIN;
DO $$ DECLARE a uuid;s uuid;m uuid;c uuid;other uuid;r jsonb;w uuid;j uuid;ev uuid;BEGIN
 INSERT INTO public.admin_users(email,password_hash,role,is_active) VALUES('card-bind-owner@example.test','fixture','super_admin',true) RETURNING id INTO a;
 INSERT INTO public.admin_sessions(admin_user_id,token_hash) VALUES(a,repeat('f1',32)) RETURNING id INTO s;
 INSERT INTO public.members(name,email) VALUES('Card Bind Fixture','card-bind@example.test') RETURNING id INTO m;
 INSERT INTO public.reward_credentials(member_id,kind,label,token_hash,encrypted_token) VALUES(m,'card','First test card',repeat('f2',32),'physical-secret') RETURNING id INTO c;
 IF EXISTS(SELECT 1 FROM public.delivery_jobs WHERE payload->>'credentialId'=c::text) THEN RAISE EXCEPTION 'Unwritten card announced';END IF;
 BEGIN PERFORM public.reward_resolve(a,s,repeat('f2',32));RAISE EXCEPTION 'Unregistered card accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'CARD_NOT_PROGRAMMED' THEN RAISE;END IF;END;
 r:=public.reward_bind_card(a,s,c,repeat('f3',32),repeat('f4',32),'digital-secret');
 IF r->>'emailQueued'<>'true' THEN RAISE EXCEPTION 'Registered card mail missing';END IF;
 SELECT digital_credential_id INTO w FROM public.reward_credentials WHERE id=c;
 IF w IS NULL OR w=c OR(SELECT token_hash FROM public.reward_credentials WHERE id=w)=repeat('f2',32) THEN RAISE EXCEPTION 'Digital credential not independent';END IF;
 r:=public.reward_bind_card(a,s,c,repeat('f3',32),repeat('f5',32),'unused-retry-secret');
 IF r->>'emailQueued'<>'false' OR(SELECT count(*) FROM public.reward_credentials WHERE member_id=m)<>2 THEN RAISE EXCEPTION 'Registration retry duplicated digital pass';END IF;
 IF public.reward_resolve_scan(a,s,repeat('f2',32),repeat('f3',32))->>'id'<>m::text THEN RAISE EXCEPTION 'Enrolled card rejected';END IF;
 BEGIN PERFORM public.reward_resolve(a,s,repeat('f2',32));RAISE EXCEPTION 'Physical token QR bypassed binding';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'CARD_SCAN_REQUIRED' THEN RAISE;END IF;END;
 BEGIN PERFORM public.reward_resolve_scan(a,s,repeat('f2',32),repeat('f6',32));RAISE EXCEPTION 'Copied chip accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'CARD_CHIP_MISMATCH' THEN RAISE;END IF;END;
 BEGIN PERFORM public.reward_bind_card(a,s,c,repeat('f6',32),repeat('f7',32),'unused');RAISE EXCEPTION 'Credential rebound to second chip';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'CARD_CHIP_MISMATCH' THEN RAISE;END IF;END;
 INSERT INTO public.reward_credentials(member_id,kind,label,token_hash,encrypted_token) VALUES(m,'card','Second test card',repeat('f8',32),'second-physical') RETURNING id INTO other;
 BEGIN PERFORM public.reward_bind_card(a,s,other,repeat('f3',32),repeat('f9',32),'unused');RAISE EXCEPTION 'Chip bound to two credentials';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'CARD_ALREADY_REGISTERED' THEN RAISE;END IF;END;
 SELECT id INTO j FROM public.delivery_jobs WHERE payload->>'credentialId'=c::text;
 r:=public.reward_email_pass(j);
 IF r->>'encryptedToken'<>'digital-secret' OR r->>'id'<>c::text OR r->>'passId'<>w::text THEN RAISE EXCEPTION 'Mail exposes physical credential';END IF;
 IF public.reward_resolve(a,s,repeat('f4',32))->>'id'<>m::text THEN RAISE EXCEPTION 'Wallet QR failed';END IF;
 INSERT INTO public.reward_event_connections(title,origin,opens_at,closes_at,is_active,key_hash,encrypted_key) VALUES('Chip test event','https://event.example.test/',now()-interval '1 hour',now()+interval '1 hour',true,repeat('fa',32),'fixture') RETURNING id INTO ev;
 BEGIN PERFORM public.reward_event_admin(a,s,'lookup',jsonb_build_object('eventId',ev,'credentialHash',repeat('f2',32)));RAISE EXCEPTION 'Event bypassed chip binding';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'CARD_SCAN_REQUIRED' THEN RAISE;END IF;END;
 r:=public.reward_event_admin(a,s,'lookup',jsonb_build_object('eventId',ev,'credentialHash',repeat('f2',32),'cardUidHash',repeat('f3',32)));
 IF r->'member'->>'id'<>m::text THEN RAISE EXCEPTION 'Enrolled event card failed';END IF;
 UPDATE public.reward_credentials SET revoked_at=now() WHERE id=c;
 BEGIN PERFORM public.reward_resolve_scan(a,s,repeat('f2',32),repeat('f3',32));RAISE EXCEPTION 'Revoked chip worked';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 IF public.reward_email_pass(j) IS NOT NULL THEN RAISE EXCEPTION 'Revoked physical email capability worked';END IF;
 IF public.reward_resolve(a,s,repeat('f4',32))->>'id'<>m::text THEN RAISE EXCEPTION 'Lost physical card incorrectly revoked independent Wallet';END IF;
 IF has_function_privilege('anon','public.reward_bind_card(uuid,uuid,uuid,text,text,text)','EXECUTE') OR has_function_privilege('authenticated','public.reward_resolve_scan(uuid,uuid,text,text)','EXECUTE') THEN RAISE EXCEPTION 'Chip APIs exposed';END IF;
END $$;
DO $$ DECLARE a uuid;s uuid;f uuid;v uuid;r uuid;n uuid;j public.delivery_jobs;definition jsonb;
BEGIN
 INSERT INTO public.admin_users(email,password_hash,role,is_active) VALUES('withdrawn-push@example.test','fixture','super_admin',true) RETURNING id INTO a;
 INSERT INTO public.admin_sessions(admin_user_id,token_hash) VALUES(a,repeat('b9',32)) RETURNING id INTO s;
 PERFORM public.register_app_notification_device(a,s,gen_random_uuid(),'ios','production',repeat('ba',32),'encrypted-fixture','Test iPhone');
 definition:=jsonb_build_object('fields','[]'::jsonb,'sections','[]'::jsonb,'settings','{}'::jsonb);
 INSERT INTO public.forms(slug,title,owner_id,draft_definition,state) VALUES('withdrawn-push','Withdrawn push fixture',a,definition,'Open') RETURNING id INTO f;
 INSERT INTO public.form_versions(form_id,version,definition,schema_hash,published_by) VALUES(f,1,definition,repeat('b',64),a) RETURNING id INTO v;
 UPDATE public.forms SET published_version_id=v WHERE id=f;
 INSERT INTO public.form_responses(form_id,version_id,submitted_at,idempotency_key_hash,request_hash) VALUES(f,v,now(),repeat('bc',32),repeat('bd',32)) RETURNING id INTO r;
 SELECT id INTO n FROM public.notifications WHERE delivery_key='form-response:'||r||':'||a;
 SELECT * INTO j FROM public.delivery_jobs WHERE kind='app_push_ios' AND payload->>'notificationId'=n::text;
 UPDATE public.delivery_jobs SET state='running',lease_token=gen_random_uuid(),locked_until=now()+interval '1 minute' WHERE id=j.id RETURNING * INTO j;
 IF public.prepare_app_push(j.id,j.lease_token) IS NULL THEN RAISE EXCEPTION 'Active response push missing';END IF;
 UPDATE public.form_responses SET redacted_at=now() WHERE id=r;
 IF public.prepare_app_push(j.id,j.lease_token) IS NOT NULL THEN RAISE EXCEPTION 'Withdrawn response alert sent';END IF;
END $$;
ROLLBACK;
